from typing import Dict, Any

class PlatformModelRequest:
    def __init__(self, text: str, parameters: Dict[str, Any] = None):
        self.text = text
        self.parameters = parameters if parameters is not None else {}

    def to_bedrock_converse_format(self):
        # A basic conversion for the text-only use case demonstrated
        return {"messages": [{"role": "user", "content": [{"text": self.text}]}]}

class PlatformModelResponse:
    def __init__(self, text: str, metadata: Dict[str, Any] = None, raw_response: Dict[str, Any] = None):
        self.text = text
        self.metadata = metadata if metadata is not None else {}
        self.raw_response = raw_response if raw_response is not None else {}

    @classmethod
    def from_bedrock_converse_response(cls, response: Dict[str, Any]):
        text = "".join(block["text"] for block in response["output"]["message"]["content"] if "text" in block)
        metadata = {"usage": response.get("usage"), "model_id": response["output"]["message"]["modelId"]}
        return cls(text=text, metadata=metadata, raw_response=response)

import boto3

def localized_platform_output(text_output, target_language_code, config=None):
    config = config or {}
    client = boto3.client("translate", region_name=config.get("region", "us-east-1"))

    response = client.translate_text(
        Text=text_output,
        SourceLanguageCode="auto", # Automatically detect source language
        TargetLanguageCode=target_language_code
    )

    translated_text = response["TranslatedText"]
    source_language = response["SourceLanguageCode"]

    return {"translated_text": translated_text, "source_language": source_language, "target_language": target_language_code}

import boto3
from botocore.exceptions import ClientError

def platform_brief_audio(text_output, voice_id="Joanna", config=None):
    config = config or {}
    client = boto3.client("polly", region_name=config.get("region", "us-east-1"))

    try:
        response = client.synthesize_speech(
            Text=text_output,
            OutputFormat="mp3",
            VoiceId=voice_id
        )

        # The audio stream is in response["AudioStream"]
        # For this example, we will return the raw audio stream content.
        # In a real application, you would save this to a file or stream it directly.
        audio_stream_content = response["AudioStream"].read()

        return {"audio_content": audio_stream_content, "format": "mp3", "voice_id": voice_id}
    except ClientError as e:
        print(f"Error synthesizing speech: {e}")
        return {"error": str(e)}
